import{_ as d,l as s,o as a,c as l,v as i,p as n,x as r,d as o,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"SCHED_DEADLINE","description":"","frontmatter":{"title":"SCHED_DEADLINE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sched-deadline.md","filePath":"cs/sched-deadline.md","lastUpdated":1789023840000}'),h={name:"cs/sched-deadline.md"};function D(_,e,p,u,m,C){const t=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=i('<h1 id="sched-deadline" tabindex="-1">SCHED_DEADLINE <a class="header-anchor" href="#sched-deadline" aria-label="Permalink to &quot;SCHED_DEADLINE&quot;">​</a></h1><div class="epigraph"><p>SCHED_DEADLINE 实现 CBS：任务申报运行时、周期与截止，内核保证在截止前给够预算，否则节流。</p><footer>—— 据 Linux sched-deadline 文档；Abeni 与 Buttazzo 对 CBS 的论述；POSIX sporatic server 直觉</footer></div><p><a href="/cs/eevdf">EEVDF</a> 是尽力公平。<a href="/cs/heterogeneous-core-sched">异构</a> 是容量。硬实时要 <strong>带宽隔离</strong>。缺口是 deadline 调度类：全局 EDF + CBS，不是用户写一个定时器循环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>sched_setattr</code>：runtime ≤ deadline ≤ period。准入：总和不超过 CPU 带宽（可留 5% 给其它）。运行：EDF 选最早截止，用尽 runtime 则节流到下周期。缺口：与 FIFO/RR 的优先级关系（DL 高于 RT 高于 CFS，通常）；fork 不继承；亲和与全局队列。本课不把 GEDF 可调度性证明展开成课程。</p><p><span class="marginnote">错过截止会统计，不自动变 CFS。对象是 CPU 时间，不是磁盘 deadline 调度器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>准入会计 → 入 DL 队列。tick/hrtimer 扣 runtime。对照 <a href="/cs/blk-schedulers">blk mq-deadline</a>：名字像，对象不是 bio。对照 <a href="/cs/memcg">memcg</a>：一个限内存，一个限 CPU 时间形状。对照 EAS：DL 任务往往不参与省电迁移。</p>',8)),(a(),n(c,null,{default:r(()=>[E(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADM%5B%22%E5%B8%A6%E5%AE%BD%E5%87%86%E5%85%A5%22%5D%20--%3E%20RUN%5B%22EDF%20%E9%80%89%E6%9C%80%E6%97%A9%E6%88%AA%E6%AD%A2%22%5D%0A%20%20RUN%20--%3E%20BUD%5B%22%E6%B6%88%E8%80%97%20runtime%22%5D%0A%20%20BUD%20--%3E%7C%22%E8%80%97%E5%B0%BD%22%7C%20THR%5B%22%E8%8A%82%E6%B5%81%E5%88%B0%E4%B8%8B%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CBS 把「周期性工作」收成内核保证，使媒体与控制回路不必靠 nice。过载被准入挡住，而不是大家一起错过。不要写成航空认证。与 <a href="/cs/napi">NAPI</a>：硬中断仍可拉延迟，后课 PREEMPT_RT。</p><p>用户必须诚实申报；瞒报 runtime 会自己被节流。</p><p>实现上：runtime 用尽会节流到下周期，看起来像卡顿而不是降 nice。全局 EDF 在多核上要迁任务，亲和会破坏保证。用户必须用 SCHED_FLAG_RESET_ON_FORK 避免子进程继承。 读法上只引用<a href="/cs/heterogeneous-core-sched">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>SCHED_DEADLINE</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DL 服务器给 CFS 的全部。不保证与 cgroup cpu.max 的每一种组合直观。下一课把内核变成可抢占实时：PREEMPT_RT。</p><p>版本字段会变，课序钉的是机制对象「SCHED_DEADLINE」，不是某一主线内核的结构体名。 后课默认：CPU 可按 CBS 保证预算。完全抢占内核，下一课 PREEMPT_RT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SCHED_DEADLINE：CBS 预算 + EDF 选择 + 准入。</li><li>高于普通 CFS/RT 的一类（常规配置）。</li><li>PREEMPT_RT 是下一课。</li><li>出处：Linux sched-deadline；CBS 文献。</li></ul>',11))])}const T=d(h,[["render",D]]);export{A as __pageData,T as default};
